class Payload {
    Payload(const Payload&) = delete; // Explicitly forbid copy
    Payload(Payload&&) = default;
};

// 1. NRVO Candidate (Named Return Value Optimization)
Payload create_named() {
    Payload result; // Named local variable
    return result;  // Compiler optimizes away copy/move
}

// 2. RVO Candidate (Simple Return Value Optimization)
Payload create_unnamed() {
    // Returns unnamed temporary
    return Payload(); // Guaranteed copy elision (C++17+)
}
